 position: fixed;
 left: 0;
 right: 0;
 top: 0;
 height: 100%;
 z-index: 9999;
}

.preloader-ring {
 position: absolute;
 width: 200px;
 height: 200px;
 border-radius: 50%;
 animation: preloader-ring 2s linear infinite;
}

.preloader-ring:before {
 position: absolute;
 content: '';
 left: 0;
 top: 0;
 height: 100%;
 width: 100%;
 border-radius: 50%;
 box-shadow: 0 0 5px rgba(255, 255, 255, .3);
}

