/* Product Variations */
#shopping-cart-container table.cart-products .variation_select {
    padding: 0;
    margin: 0;
    margin-top: 1px;
    max-width: 100%;
}

.chosen_variation {
    display: block;
    font-style: italic;
}

.variation_select, .boxed #product_details .variation_select {
    margin-bottom: 5px;
    min-width: 100px;
    width: 100%;
    max-width: 100%;
}

input[type='text'].variation_select, .boxed #product_details input[type='text'].variation_select {
    padding: 15px 10px;
}

.variation-select-container {
    margin-bottom: 5px;
}

.boxed #product_details .variation_select:last-of-type {
    margin-bottom: 0;
}

article.variable-single-price-effect .product-entry .price-container, .boxed.variable-single-price-effect #product_details > div.price-container, #content .boxed.variable-single-price-effect #product_details > div.price-container,
article.variable-single-price-effect .product-entry .shipping-table-container, .boxed.variable-price-effect #product_details > div.shipping-table-container, #content .boxed.variable-single-price-effect #product_details > div.shipping-table-container,
article.variable-single-price-effect .product-entry .sku-table, .boxed.variable-single-price-effect #product_details > div.sku-table, #content .boxed.variable-single-price-effect #product_details > div.sku-table {
    opacity:0;
}


.ic_spinner, .boxed #product_details .ic_spinner {
    display: inline-block;
    opacity: 0.7;
    width: 20px !important;
    height: 20px;
    margin-left: 2px;
    vertical-align: middle;
    display: none;
}

@media (max-width: 1000px) {
    .table-listing-element .variation_select {
        min-width: 50px;
        max-width: 79px;
    }
}

/*
    Colorbox Core Style:
    The following CSS is consistent between example themes and should not be altered.
*/
#colorbox, #cboxOverlay, #cboxWrapper {
    position: absolute;
    top: 0;
    left: 0;
    z-index: 9999;
    overflow: hidden;
    -webkit-transform: translate3d(0, 0, 0);
}

#cboxWrapper {
    max-width: none;
}

#cboxOverlay {
    position: fixed;
    width: 100%;
    height: 100%;
}

#cboxMiddleLeft, #cboxBottomLeft {
    clear: left;
}

#cboxContent {
    position: relative;
}

#cboxLoadedContent {
    overflow: auto;
    -webkit-overflow-scrolling: touch;
}

#cboxTitle {
    margin: 0;
}

#cboxLoadingOverlay, #cboxLoadingGraphic {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

#cboxPrevious, #cboxNext, #cboxClose, #cboxSlideshow {
    cursor: pointer;
}

.cboxPhoto {
    float: left;
    margin: auto;
    border: 0;
    display: block;
    max-width: none;
    -ms-interpolation-mode: bicubic;
}

.cboxIframe {
    width: 100%;
    height: 100%;
    display: block;
    border: 0;
    padding: 0;
    margin: 0;
}

#colorbox, #cboxContent, #cboxLoadedContent {
    box-sizing: content-box;
    -moz-box-sizing: content-box;
    -webkit-box-sizing: content-box;
}

/*
    User Style:
    Change the following styles to modify the appearance of Colorbox.  They are
    ordered & tabbed in a way that represents the nesting of the generated HTML.
*/
#cboxOverlay {
    background: #fff;
    opacity: 0.9;
}

#colorbox {
    outline: 0;
}

#cboxTopLeft {
    width: 25px;
    height: 25px;
    background: url(images/border1.png) no-repeat 0 0;
}

#cboxTopCenter {
    height: 25px;
    background: url(images/border1.png) repeat-x 0 -50px;
}

#cboxTopRight {
    width: 25px;
    height: 25px;
    background: url(images/border1.png) no-repeat -25px 0;
}

#cboxBottomLeft {
    width: 25px;
    height: 25px;
    background: url(images/border1.png) no-repeat 0 -25px;
}

#cboxBottomCenter {
    height: 25px;
    background: url(images/border1.png) repeat-x 0 -75px;
}

#cboxBottomRight {
    width: 25px;
    height: 25px;
    background: url(images/border1.png) no-repeat -25px -25px;
}

#cboxMiddleLeft {
    width: 25px;
    background: url(images/border2.png) repeat-y 0 0;
}

#cboxMiddleRight {
    width: 25px;
    background: url(images/border2.png) repeat-y -25px 0;
}

#cboxContent {
    background: #fff;
    overflow: hidden;
}

.cboxIframe {
    background: #fff;
}

#cboxError {
    padding: 50px;
    border: 1px solid #ccc;
}

#cboxLoadedContent {
    margin-bottom: 20px;
}

#cboxTitle {
    position: absolute;
    bottom: 0px;
    left: 0;
    text-align: center;
    width: 100%;
    color: #999;
}

#cboxCurrent {
    position: absolute;
    bottom: 0px;
    left: 130px;
    color: #999;
}

#cboxLoadingOverlay {
    background: #fff url(images/loading.gif) no-repeat 5px 5px;
}

/* these elements are buttons, and may need to have additional styles reset to avoid unwanted base styles */
#cboxPrevious, #cboxNext, #cboxSlideshow, #cboxClose {
    border: 0;
    padding: 0;
    margin: 0;
    overflow: visible;
    width: auto;
    background: none;
}

/* avoid outlines on :active (mouseclick), but preserve outlines on :focus (tabbed navigating) */
#cboxPrevious:active, #cboxNext:active, #cboxSlideshow:active, #cboxClose:active {
    outline: 0;
}

#cboxSlideshow {
    position: absolute;
    bottom: 0px;
    right: 42px;
    color: #444;
}

#cboxPrevious {
    position: absolute;
    bottom: 0px;
    left: 0;
    color: #444;
}

#cboxNext {
    position: absolute;
    bottom: 0px;
    left: 63px;
    color: #444;
}

#cboxClose {
    position: absolute;
    bottom: 0;
    right: 0;
    display: block;
    color: #444;
}

/*
  The following fixes a problem where IE7 and IE8 replace a PNG's alpha transparency with a black fill
  when an alpha filter (opacity change) is set on the element or ancestor element.  This style is not applied to or needed in IE9.
  See: http://jacklmoore.com/notes/ie-transparency-problems/
*/
.cboxIE #cboxTopLeft,
.cboxIE #cboxTopCenter,
.cboxIE #cboxTopRight,
.cboxIE #cboxBottomLeft,
.cboxIE #cboxBottomCenter,
.cboxIE #cboxBottomRight,
.cboxIE #cboxMiddleLeft,
.cboxIE #cboxMiddleRight {
    filter: progid:DXImageTransform.Microsoft.gradient(startColorstr=#00FFFFFF, endColorstr=#00FFFFFF);
}

div#cboxContent button {
    font-size: 15px;
}

