/*
 * Scrool and sticky meny
 */
.backtotop {
    background-color: var(--gbl-primary-color);
    z-index: 300;
    width: 40px;
    height: 40px;
    line-height: 40px;
    border-radius: 100%;
    font-size: 20px;
    text-align: center;
    position: fixed;
    bottom: -100px;
    right: 10px;
    cursor: pointer;
    -webkit-transition: all .7s ease-in-out;
    -moz-transition: all .7s ease-in-out;
    -o-transition: all .7s ease-in-out;
    -ms-transition: all .7s ease-in-out;
    transition: all .7s ease-in-out;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.6;
}

.backtotop svg {
    fill: white;   
}

.addtocart_btn {
    z-index: 300;
    border-radius: 100%;
    font-size: 13px;
    text-align: center;
    position: fixed;
    bottom: -100px;
    right: 0px;
    cursor: pointer;
    -webkit-transition: all .7s ease-in-out;
    -moz-transition: all .7s ease-in-out;
    -o-transition: all .7s ease-in-out;
    -ms-transition: all .7s ease-in-out;
    transition: all .7s ease-in-out;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0.9;
}

.addtocart_btn .woocommerce a.added_to_cart {
  padding-top: .5em;
  font-size: 12px;
  display: block;
}

body.custom-background-image .addtocart_btn .woocommerce a.added_to_cart , 
body.custom-background-color .addtocart_btn .woocommerce a.added_to_cart {
    color: var(--gbl-secondary-color);
}

