body.aft-default-mode .aft-popular-taxonomies-lists{background: rgba(0,0,0,0.05)}

.aft-popular-taxonomies-lists strong {
    margin-right: 20px;
    color: #fff;
    position: relative;
    padding: 10px 15px;
    z-index: 0;
    
}
.aft-popular-taxonomies-lists strong:before {
    position: absolute;
    content: '';
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    background-color: var(--gbl-primary-color);
    z-index: -1;
}


.aft-dark-mode .aft-popular-taxonomies-lists strong:before {
    background-color: #fff;
}
.aft-popular-taxonomies-lists strong:after {
    content: '';
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    left: 100%;
    border-color: transparent transparent transparent var(--gbl-primary-color);
    border-style: solid;
    border-width: .7em;
}
.aft-dark-mode .aft-popular-taxonomies-lists strong:after {
    border-color: transparent transparent transparent #fff;
}
.aft-popular-taxonomies-lists ul {
    display: inline-block;
}

.aft-popular-taxonomies-lists ul li {
    display: inline-block;
    margin-right: 20px;
}

.aft-popular-taxonomies-lists ul li a {
    transition: all 0.5s linear;
}

.aft-popular-taxonomies-lists ul li a:before {
    content: '#';
    font-size: 15px;
    padding: 0 5px;
    font-weight: 500;
}

/*aft-popular-taxonomies-lists-----*/


/*exclusive posts-----*/

.banner-exclusive-posts-wrapper{
    position: relative;
}
.banner-exclusive-posts-wrapper .exclusive-posts:before{
    position: absolute;
    content: '';
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    background-color: #000;
    opacity: 0.1;
}
.aft-dark-mode .banner-exclusive-posts-wrapper .exclusive-posts:before{
    background-color: #fff;
}

.banner-exclusive-posts-wrapper a,
.banner-exclusive-posts-wrapper a:visited{
    transition: all 0.5s linear;
}

.banner-exclusive-posts-wrapper a:hover,
.banner-exclusive-posts-wrapper a:visited:hover{
    color: #bb1919;
}

.banner-exclusive-posts-wrapper .aft-ripple {
    display: inline-block;
    position: relative;
    min-width: 30px;
    width: 50px;
    min-height: 50px;
    height: 50px;
    display: flex;
    justify-content: center;
    align-items: center;
    background: rgba(0,0,0,.22);
}
.banner-exclusive-posts-wrapper .aft-ripple div {
    position: absolute;
    border: 3px solid #ffffff;
    opacity: 1;
    border-radius: 50%;
    top: 50%;
    left: 50%;
    -o-transform: translate(-50%, -50%);
    -moz-transform: translate(-50%, -50%);
    -ms-transform: translate(-50%, -50%);
    -webkit-transform: translate(-50%, -50%);
    transform:translate(-50% , -50%);
    animation: aft-ripple 1.3s cubic-bezier(0, 0.2, 0.8, 1) infinite;
}
.banner-exclusive-posts-wrapper .aft-ripple div:nth-child(2) {
    animation-delay: -0.5s;
}
@keyframes aft-ripple{
    0% {
        width: 0;
        height: 0;
        opacity: 1;
    }
    100% {
        width: 38px;
        height: 38px;
        opacity: 0;
    }
}

.exclusive-posts {
    font-size: 14px;
    /* line-height: 50px; */
    margin: 0px;
    position: relative;
}

/* exclusive post refinement */
.marquee.aft-flash-slide > div {
    display: flex;
    height: 50px;
    overflow: hidden;
}
.circle-marq-title{
  display: inline-block;
  vertical-align: middle;
}
.exclusive-posts .marquee a span.circle-marq {
  vertical-align: middle;
}
/* exclusive post refinement */

.exclusive-posts .exclusive-now {
    background: var(--gbl-primary-color);
    color: #ffffff;
    float: left;
    text-transform: uppercase;
    position: relative;
    padding: 0 15px;
    padding-left: 0;
    margin-right: 5px;
    display: flex;
    align-items: center;
    min-height: 50px;
    font-weight: 700;
}
.exclusive-posts .exclusive-now span{
    margin-left: 15px;
    display: inline-block;
}

.exclusive-slides {
    padding: 0 5px;
    overflow: hidden;
    position: relative;
}

.exclusive-slides .marquee {
    width: 10000px;
}

.exclusive-posts .marquee a {
    padding: 5px 25px;
    font-weight: bold;
    align-items: center;
    display: inline-block;
}

.exclusive-posts .marquee a span.circle-marq {
    width: 40px;
    height: 40px;
    overflow: hidden;
    display: inline-block;
    line-height: 1;
    margin-right: 10px;
    position: relative;
}

.exclusive-posts .marquee a img {
    height: 40px;
    width: 40px;
    object-fit: cover;
}

.exclusive-posts .marquee a span.circle-marq .trending-no {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    color: #fff;
    background: rgba(28, 28, 28, 0.5);
    text-align: center;
    line-height: 39px;
    font-size: 18px;
    font-weight: 700;
}

/*----exclusive posts----*/


.products > .product .hover-area .yith-wcwl-add-button a span {
	display:none;
}


.woocommerce ul.products li.product .hover-area .button {
  padding: 16px;
}

.wc-block-grid__products li, .entry-content .wc-block-grid__products li {
    list-style: none;
}


/* Page numbering */

@media (max-width: 1024px) {
    
    .navigation .nav-links {
        clear: both;
        padding-top: 10px;
    }
    
}

/* Fix for currency symbol issues */
.woocommerce-Price-currencySymbol,
.amount-cart {
  font-family: "Source Sans Pro","HelveticaNeue-Light","Helvetica Neue Light","Helvetica Neue",Helvetica,Arial,"Lucida Grande",sans-serif;
}


/* 
 * Timer styles 
 */
.countdown-item {
    text-align: center;
    max-width: 25%;
    width: 25%;
    float: left;
    line-height: 16px;
    font-size: 10px;
    margin-right: 6px;
    color: #000;
    letter-spacing: -.5px
}
.countdown-item:last-child {
    margin-right: 0
}
.countdown-item span {
    display: block;
    padding: 3px;
    border: 1px solid;
    font-size: 14px;
    line-height: 16px;
    border: none;
    border-radius: 3px;
    position: relative
}
.countdown-item span:after {
    content: ":";
    position: absolute;
    right: -5px;
    font-weight: 700
}
.countdown-item:last-child span:after {
    display: none
}
.the-countdown {
    display: flex;
    float: none;
    align-items: center;
    justify-content: space-between;
    position: relative;
    margin-bottom: 10px;
    padding: 0 15px
}
.the-countdown-notice {
    display: block;
    clear: both;
    font-size: 13px;
    line-height: 18px;
    padding: 5px 15px 8px
}


.products > .product .hover-area .yith-wcwl-add-to-wishlist.exists {
	display:none;
}

