/********************************
 * aft-popular-taxonomies-lists *
 ********************************/

.aft-popular-tags {
    font-size: 14px;
    position: relative;
}
.aft-popular-tags ul {
    margin: 0px;
}
.banner-exclusive-posts-wrapper { }
