}
mark, ins {
    text-decoration: none;
}
big {
    font-size: 125%;
}
/* Media
--------------------------------------------- */
.page-content .wp-smiley, .entry-content .wp-smiley, .comment-content .wp-smiley {
    border: none;
    margin-bottom: 0;
    margin-top: 0;
